INSERT INTO pg_temp.ref_public_recipe_ingredients (id, recipe_revision_id, ingredient_revision_id, "position", quantity, unit, grams, optional, included_by_default, substitution_group, prep_note, substitution_note) VALUES ('00000000-0000-4000-8000-000000451105', '00000000-0000-4000-8000-000000440011', '00000000-0000-4000-8000-000000420012', 5, 0.5, 'tsp', 3, false, true, NULL, NULL, NULL);
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('32adf185-319b-4e46-be2f-f77c52714bf8', '00000000-0000-4000-8000-000000440001', 1, 'Crumble the tofu into a bowl with your hands. Aim for uneven pieces about the size of a pea, with a few larger ones.', NULL, 'Crumble the tofu');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('17ff5fde-f314-4029-9b5f-cd5dda7c848f', '00000000-0000-4000-8000-000000440001', 2, 'Warm the oil in the pan over medium heat. Add the onion and the chili, if using, and cook until soft and just turning golden. Stir now and then.', 300, 'Soften the onion');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('3b4ddb6a-e45d-4555-9601-1c3042497032', '00000000-0000-4000-8000-000000440001', 3, 'Add the tomato, turmeric, cumin and salt. Cook until the tomato breaks down and the pan looks jammy.', 180, 'Add tomato and spices');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('631b776a-be67-4022-881e-891ab0b1ef5c', '00000000-0000-4000-8000-000000440001', 4, 'Stir in the tofu so every piece turns yellow. Cook, stirring gently, until it is hot all the way through and most of the liquid has gone.', 240, 'Cook the tofu');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('df404be0-0195-4434-a79d-629c8f7f4494', '00000000-0000-4000-8000-000000440001', 5, 'Fold in the spinach and cook for one minute, just until it wilts. Taste and add a pinch more salt if it needs it.', 60, 'Wilt the spinach');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('a89217af-46f5-4d5f-bb00-081c9a71b7af', '00000000-0000-4000-8000-000000440001', 6, 'Scatter over the coriander, if using, and serve straight away.', NULL, 'Serve');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('8d2f5ad0-26a1-46ab-9480-5b4d2caa9db1', '00000000-0000-4000-8000-000000440002', 1, 'Put the oats and chia seeds in the jar. Pour in the milk, add the peanut butter and the sweetener, and stir well until no dry pockets remain.', NULL, 'Mix');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('e2ec2e13-c3a4-4e71-84ff-e6ba13ec9411', '00000000-0000-4000-8000-000000440002', 2, 'Put the lid on and leave in the fridge overnight, or for at least 6 hours. The oats and chia will soak up the liquid and thicken.', NULL, 'Rest');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('a1a0a145-b79d-471f-a370-fae123e993f8', '00000000-0000-4000-8000-000000440002', 3, 'Stir once more. Loosen with a splash of milk if it is thicker than you like, then top with the sliced banana.', NULL, 'Serve');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('a2a2b3ec-b691-4b12-bf43-dbea55c2c843', '00000000-0000-4000-8000-000000440003', 1, 'Put the walnuts in a dry pan over medium heat. Shake the pan often until they smell toasty. Tip them out so they stop cooking.', 180, 'Toast the walnuts');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('b8822a06-2eb2-468c-bec3-7ca217ebe312', '00000000-0000-4000-8000-000000440003', 2, 'Spoon the yogurt into a bowl. Top with the berries, the walnuts and the chia seeds.', NULL, 'Build the bowl');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('1a74a17c-1c1b-4358-bb97-f6fa0e67aea5', '00000000-0000-4000-8000-000000440003', 3, 'Drizzle the sweetener over the top and eat straight away.', NULL, 'Finish');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('b538294b-5777-4eb0-81f2-e1a6143e9d8e', '00000000-0000-4000-8000-000000440004', 1, 'Warm the oil in the pan over medium heat. Add the onion and pepper and cook until soft and sweet. Stir now and then.', 420, 'Soften the vegetables');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('04229f92-a66c-4b34-aa7d-79b19f5b6fa3', '00000000-0000-4000-8000-000000440004', 2, 'Stir in the garlic, smoked paprika and cumin and cook for one minute, until fragrant.', 60, 'Add garlic and spices');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('82a2ed54-f905-4edc-8116-24490e6e199d', '00000000-0000-4000-8000-000000440004', 3, 'Pour in the chopped tomatoes and add the salt. Simmer until the sauce thickens enough to hold a dip made with the back of a spoon.', 480, 'Simmer the sauce');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('063b5acb-115e-46e7-a65b-cc770520d835', '00000000-0000-4000-8000-000000440004', 4, 'If using eggs, make four dips in the sauce and crack an egg into each. Put the lid on and cook until the whites are set and the yolks are as soft as you like. If using beans, stir them in, put the lid on and warm through.', 300, 'Add the eggs or beans');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('658625ac-737b-48fb-9c78-6c636c9916e4', '00000000-0000-4000-8000-000000440004', 5, 'Take the pan off the heat. Scatter over the parsley, if using, and bring the pan to the table.', NULL, 'Serve');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('739d6135-28fe-4173-b55a-2a29d38a6638', '00000000-0000-4000-8000-000000440005', 1, 'Warm the oil in the pot over medium heat. Add the onions and cook until deep golden. This is where the flavour comes from, so give it time and stir now and then.', 480, 'Brown the onions');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('577b9154-c6bd-48d6-96c1-3acf56168829', '00000000-0000-4000-8000-000000440005', 2, 'Stir in the garlic and ginger and cook for one minute. Add the garam masala, cumin and turmeric and stir for 30 seconds so the spices toast without burning.', 90, 'Add garlic, ginger and spices');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('bfcbd1e7-d16c-422e-8d34-b98ee19ec9a6', '00000000-0000-4000-8000-000000440005', 3, 'Add the chopped tomatoes and salt. Cook until the tomatoes darken and the oil starts to show at the edges.', 300, 'Make the gravy');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('ae09e017-4061-440e-b516-f1501745bdfd', '00000000-0000-4000-8000-000000440005', 4, 'Add the chickpeas and the water. Bring to a gentle bubble, then simmer without a lid until the gravy coats the chickpeas. Crush a few against the side of the pot to thicken it.', 600, 'Simmer the chickpeas');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('ed7cac6e-629e-4f4f-9ae8-19c727794025', '00000000-0000-4000-8000-000000440005', 5, 'Stir in the lemon juice. Taste, adjust the salt, and scatter over the coriander, if using.', NULL, 'Finish and serve');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('e8758052-66b3-4cac-8d4e-141fe642b41e', '00000000-0000-4000-8000-000000440006', 1, 'Bring a pot of water to the boil. Push the spinach under for one minute, then drain and rinse under cold water so it stays green. Squeeze out most of the water.', 60, 'Blanch the spinach');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('710b2985-f456-4ac6-a96e-527ef1bff34d', '00000000-0000-4000-8000-000000440006', 2, 'Warm the oil in the frying pan over medium-high heat. Add the paneer or tofu cubes and turn them until golden on most sides. Lift them out onto a plate.', 300, 'Brown the cubes');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('3e9cf4e0-49d1-4fcc-9aa9-c8d5303dc73a', '00000000-0000-4000-8000-000000440006', 3, 'In the same pan, cook the onion until soft. Add the garlic, ginger and tomato and cook until the tomato collapses. Stir in the garam masala, cumin and salt.', 360, 'Cook the base');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('5b892e72-2de6-4ef0-b7c0-56aad3cd8663', '00000000-0000-4000-8000-000000440006', 4, 'Tip the onion mixture and the spinach into the blender. Blend until smooth, adding a splash of water if the blades stick.', NULL, 'Blend');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('038e2d35-08d3-4df0-8722-cacef8186531', '00000000-0000-4000-8000-000000440006', 5, 'Pour the sauce back into the pan and bring to a gentle simmer. Stir in the cream or coconut milk, then return the cubes to the pan and warm through.', 240, 'Simmer together');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('42b3b0a8-db08-4eb7-b4fe-9312c892173c', '00000000-0000-4000-8000-000000440006', 6, 'Taste and adjust the salt. Serve hot.', NULL, 'Serve');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('ffc9598b-e6a4-424b-aaa9-ccb1901bd6e0', '00000000-0000-4000-8000-000000440007', 1, 'Put the lentils, water and turmeric in the pot. Bring to the boil, skim off any foam, then turn the heat down and simmer until the lentils fall apart. Stir now and then so they do not catch.', 1080, 'Simmer the lentils');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('6549c9cb-db9c-42ac-9bd9-772427c8fa39', '00000000-0000-4000-8000-000000440007', 2, 'Stir in the salt, the tomato and the spinach. Simmer until the spinach is soft. Whisk briefly if you like a smoother dal.', 240, 'Add tomato and spinach');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('bf5b9253-69dc-41b2-a252-6f6af1f01300', '00000000-0000-4000-8000-000000440007', 3, 'Warm the oil or ghee in the small pan over medium heat. Add the garlic and cook until pale gold, then add the cumin and take the pan off the heat after a few seconds.', 90, 'Sizzle the garlic and cumin');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('9b99273d-5fa4-4b61-808d-bbcdcbf7c135', '00000000-0000-4000-8000-000000440007', 4, 'Pour the hot garlic and cumin over the dal. It will sizzle. Stir in the lemon juice, taste and adjust the salt.', NULL, 'Finish');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('7c675dcc-a904-4ac5-8881-6147f7fecfc3', '00000000-0000-4000-8000-000000440008', 1, 'Put the rice in the pot with 300 ml of water and a pinch of salt. Bring to the boil, put the lid on, turn the heat to its lowest and cook without lifting the lid.', 720, 'Start the rice');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('e1969ee1-6738-4ffe-ab46-03bf2f0045e4', '00000000-0000-4000-8000-000000440008', 2, 'While the rice cooks, toss the tofu cubes with the cornstarch until lightly coated. Mix the soy sauce and maple syrup with 2 tablespoons of water in the small bowl.', NULL, 'Coat the tofu');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('ff4c865a-aafa-4bcd-aa42-b699937cd600', '00000000-0000-4000-8000-000000440008', 3, 'Heat the oil in the wok over medium-high heat. Add the tofu in one layer and leave it alone for a couple of minutes before turning, so it crisps. Cook until golden on most sides, then lift out.', 420, 'Crisp the tofu');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('231e3e8c-b96d-414e-ae61-dd4a71deaf8d', '00000000-0000-4000-8000-000000001411', 1, 'Rinse the lentils until the water runs clear.', NULL, 'Rinse');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('b1ee3417-6c4f-46a7-97de-b58ba278d046', '00000000-0000-4000-8000-000000440008', 4, 'Add the broccoli to the wok with a splash of water. Stir-fry until bright green and just tender. Add the garlic and ginger for the last 30 seconds.', 240, 'Cook the broccoli');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('58161f70-8019-4d21-aed1-26a9839b6b35', '00000000-0000-4000-8000-000000440008', 5, 'Return the tofu to the wok and pour in the sauce. Toss for a minute until everything is glossy. Take off the heat and stir in the sesame oil.', 60, 'Bring it together');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('952a8ed5-120a-4ffe-8e3c-ca7c347586c5', '00000000-0000-4000-8000-000000440008', 6, 'Fluff the rice with a fork. Spoon the stir-fry over it and scatter with the sesame seeds.', NULL, 'Serve');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('e3fd49ee-afa9-4296-8dd7-380ab251e453', '00000000-0000-4000-8000-000000440009', 1, 'Bring a pot of water to the boil. Cook the noodles for the time on the packet, adding the edamame for the last 2 minutes.', 360, 'Cook the noodles and edamame');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('d1ce8a8f-2f39-4214-8d1a-de9226073c3b', '00000000-0000-4000-8000-000000440009', 2, 'Drain the noodles and edamame and rinse under cold water until cool. Shake off as much water as you can.', NULL, 'Cool');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('c15ed5c2-dfa2-4a4b-9202-6a50d4a0f2b3', '00000000-0000-4000-8000-000000440009', 3, 'In the mixing bowl, whisk the peanut butter, soy sauce, lime juice, maple syrup, sesame oil and warm water until smooth and pourable.', NULL, 'Whisk the sauce');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('ac34e754-cb44-476a-ab19-bbae42ee407e', '00000000-0000-4000-8000-000000440009', 4, 'Add the noodles, edamame, carrot and cucumber to the bowl and toss until everything is coated. Divide between two bowls.', NULL, 'Toss and serve');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('cf9038f0-0309-4d14-bda9-d19b38be6f39', '00000000-0000-4000-8000-000000440010', 1, 'Put the quinoa and water in the pot with a pinch of the salt. Bring to the boil, put the lid on, turn the heat down low and cook until the water is absorbed.', 720, 'Cook the quinoa');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('b3bf2453-ba09-414a-b205-efe9439c63e2', '00000000-0000-4000-8000-000000440010', 2, 'Take the pot off the heat and leave it covered. This finishes the quinoa and keeps it fluffy.', 300, 'Rest');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('cb388982-ecbb-4068-aca4-4a73dbcd0195', '00000000-0000-4000-8000-000000440010', 3, 'In the small bowl, stir the tahini, lemon juice, olive oil, garlic and the rest of the salt. Add water a spoonful at a time until it pours like cream.', NULL, 'Make the dressing');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('6e4adde4-2f27-4bc9-956d-0d54e498fc45', '00000000-0000-4000-8000-000000440010', 4, 'Fluff the quinoa with a fork and divide between two bowls. Top with the chickpeas, tomato, cucumber and parsley, then spoon over the dressing.', NULL, 'Assemble');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('978b7e7f-9297-45b6-904b-2d557aacb83b', '00000000-0000-4000-8000-000000440011', 1, 'Heat the oven to 200°C (400°F). Rub the chickpeas dry in the tea towel. The drier they are, the crisper they get.', NULL, 'Heat the oven');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('cbed0679-d3fe-4fae-a1a9-e2356ef6c6be', '00000000-0000-4000-8000-000000440011', 2, 'Tip the chickpeas onto the tray. Add the olive oil, smoked paprika, cumin and salt, and roll them around until evenly coated. Spread into one layer.', NULL, 'Season');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('0b3d5c51-363c-4424-9244-244ce4355ca9', '00000000-0000-4000-8000-000000440011', 3, 'Roast until deep golden and crisp, shaking the tray halfway through.', 1500, 'Roast');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('84bd22fe-769d-480e-ac8e-c7c470b748b4', '00000000-0000-4000-8000-000000440011', 4, 'Leave on the tray for 5 minutes. They crisp up further as they cool.', 300, 'Cool');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('0e13b3f1-b743-4a64-99f2-5a21eb7bf6bb', '00000000-0000-4000-8000-000000001411', 2, 'Simmer lentils in the stock until soft.', 1500, 'Simmer');
INSERT INTO pg_temp.ref_public_recipe_steps (id, recipe_revision_id, ordinal, instruction, timer_seconds, title) VALUES ('7b4ec40d-ddfa-4fe8-bb91-4e4c953ca771', '00000000-0000-4000-8000-000000001411', 3, 'Season to taste and serve.', NULL, 'Season and serve');
